"use client";

import * as React from "react";

export type GummyButtonVariant =
  | "primary"
  | "secondary"
  | "success"
  | "warning"
  | "info";

export type GummyButtonSize = "small" | "medium" | "large";
export type GummyButtonFinish = "gel" | "translucent";

export type GummyButtonProps = React.ButtonHTMLAttributes<HTMLButtonElement> & {
  /** Fruit-colour treatment. The label remains on an optically stable layer. */
  variant?: GummyButtonVariant;
  /** Preserves a 44px minimum touch target at every visual size. */
  size?: GummyButtonSize;
  /** Controls optical transmission without changing semantic colour. */
  finish?: GummyButtonFinish;
  /** Disables activation, exposes busy state, and shows a non-motion-dependent cue. */
  loading?: boolean;
  /** Visible label while loading. */
  loadingText?: React.ReactNode;
};

function joinClassNames(...values: Array<string | false | null | undefined>) {
  return values.filter(Boolean).join(" ");
}

export const GummyButton = React.forwardRef<
  HTMLButtonElement,
  GummyButtonProps
>(function GummyButton(
  {
    variant = "primary",
    size = "medium",
    finish = "gel",
    loading = false,
    loadingText = "Loading",
    disabled = false,
    type = "button",
    className,
    children,
    ...buttonProps
  },
  ref,
) {
  const isDisabled = disabled || loading;

  return (
    <button
      {...buttonProps}
      ref={ref}
      type={type}
      className={joinClassNames("gummy-button", className)}
      data-variant={variant}
      data-size={size}
      data-finish={finish}
      data-loading={loading || undefined}
      aria-busy={loading || undefined}
      disabled={isDisabled}
    >
      <span className="gummy-button__body">
        <span className="gummy-button__content">
          {loading ? (
            <span className="gummy-button__spinner" aria-hidden="true" />
          ) : null}
          <span>{loading ? loadingText : children}</span>
        </span>
      </span>
    </button>
  );
});

GummyButton.displayName = "GummyButton";

/* Canonical Gummy Button -------------------------------------------------- */

.gummy-button {
  --gummy-light: oklch(0.92 0.1 7);
  --gummy-core: oklch(0.76 0.21 8);
  --gummy-rim: oklch(0.63 0.27 8);
  --gummy-depth: oklch(0.48 0.22 9);
  --gummy-shadow: oklch(0.62 0.25 8 / 0.3);
  --gummy-label: oklch(0.2 0.065 309);
  --gummy-thickness: 5px;
  --gummy-shadow-y: 13px;
  position: relative;
  display: inline-grid;
  min-width: max-content;
  min-height: 48px;
  place-items: center;
  padding: 0;
  border: 0;
  border-radius: 17px 20px 18px 21px / 18px 19px 17px 19px;
  background: transparent;
  color: var(--gummy-label);
  cursor: pointer;
  font-weight: 720;
  letter-spacing: -0.018em;
  line-height: 1;
  text-align: center;
  text-rendering: geometricPrecision;
  touch-action: manipulation;
  user-select: none;
  -webkit-user-select: none;
}

.gummy-button__body {
  position: relative;
  isolation: isolate;
  display: inline-grid;
  width: 100%;
  min-height: inherit;
  place-items: center;
  border: 1px solid color-mix(in oklch, var(--gummy-rim) 78%, white);
  border-bottom-color: var(--gummy-depth);
  border-radius: inherit;
  background:
    radial-gradient(ellipse 78% 66% at 50% 38%, color-mix(in oklch, var(--gummy-light) 88%, transparent) 0%, color-mix(in oklch, var(--gummy-core) 72%, transparent) 58%, transparent 78%),
    linear-gradient(155deg, color-mix(in oklch, var(--gummy-light) 90%, transparent), color-mix(in oklch, var(--gummy-core) 90%, transparent) 52%, var(--gummy-rim));
  box-shadow:
    inset 0 1px 1px color-mix(in oklch, white 68%, var(--gummy-light)),
    inset 4px 6px 10px oklch(1 0 0 / 0.22),
    inset -4px -7px 11px color-mix(in oklch, var(--gummy-depth) 34%, transparent),
    0 var(--gummy-thickness) 0 var(--gummy-depth),
    0 var(--gummy-shadow-y) 22px var(--gummy-shadow);
  transform: translateY(0) scaleX(1) scaleY(1);
  transform-origin: center bottom;
  transition:
    transform 290ms cubic-bezier(0.18, 1.62, 0.32, 1),
    border-color 180ms ease,
    background 180ms ease,
    box-shadow 240ms ease,
    filter 180ms ease,
    opacity 180ms ease;
  will-change: transform;
}

.gummy-button__body::before {
  position: absolute;
  z-index: -1;
  inset: 2px;
  padding: 2px;
  border-radius: inherit;
  background: conic-gradient(
    from 218deg,
    transparent 0 10%,
    oklch(1 0 0 / 0.12) 16%,
    oklch(1 0 0 / 0.88) 25%,
    oklch(1 0 0 / 0.26) 34%,
    transparent 45% 100%
  );
  content: "";
  mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  mask-composite: exclude;
  pointer-events: none;
}

.gummy-button__body::after {
  position: absolute;
  z-index: -1;
  top: 8%;
  left: 12%;
  width: 22%;
  height: 18%;
  border-radius: 50%;
  background: radial-gradient(ellipse, oklch(1 0 0 / 0.78), oklch(1 0 0 / 0.08) 52%, transparent 72%);
  content: "";
  filter: blur(0.35px);
  pointer-events: none;
  transform: rotate(-5deg);
}

.gummy-button__content {
  position: relative;
  z-index: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  white-space: nowrap;
}

.gummy-button[data-size="small"] {
  min-height: 44px;
  border-radius: 15px 17px 16px 18px / 16px 17px 15px 17px;
  font-size: 13px;
}

.gummy-button[data-size="small"] .gummy-button__body {
  padding: 10px 17px 11px;
}

.gummy-button[data-size="medium"] {
  font-size: 15px;
}

.gummy-button[data-size="medium"] .gummy-button__body {
  padding: 13px 23px 14px;
}

.gummy-button[data-size="large"] {
  min-height: 56px;
  border-radius: 19px 23px 20px 24px / 21px 22px 19px 22px;
  font-size: 17px;
}

.gummy-button[data-size="large"] .gummy-button__body {
  padding: 16px 29px 17px;
}

.gummy-button[data-variant="secondary"] {
  --gummy-light: oklch(0.9 0.1 303);
  --gummy-core: oklch(0.76 0.18 302);
  --gummy-rim: oklch(0.62 0.22 302);
  --gummy-depth: oklch(0.46 0.18 302);
  --gummy-shadow: oklch(0.58 0.2 302 / 0.29);
}

.gummy-button[data-variant="success"] {
  --gummy-light: oklch(0.97 0.11 126);
  --gummy-core: oklch(0.89 0.22 126);
  --gummy-rim: oklch(0.76 0.22 126);
  --gummy-depth: oklch(0.59 0.17 126);
  --gummy-shadow: oklch(0.7 0.18 126 / 0.3);
}

.gummy-button[data-variant="warning"] {
  --gummy-light: oklch(0.96 0.11 70);
  --gummy-core: oklch(0.85 0.2 58);
  --gummy-rim: oklch(0.72 0.2 49);
  --gummy-depth: oklch(0.56 0.18 45);
  --gummy-shadow: oklch(0.7 0.2 52 / 0.3);
}

.gummy-button[data-variant="info"] {
  --gummy-light: oklch(0.96 0.09 205);
  --gummy-core: oklch(0.84 0.15 207);
  --gummy-rim: oklch(0.7 0.17 218);
  --gummy-depth: oklch(0.52 0.14 226);
  --gummy-shadow: oklch(0.66 0.16 215 / 0.3);
}

.gummy-button[data-finish="translucent"] {
  --gummy-thickness: 2px;
  --gummy-shadow-y: 10px;
  min-height: 58px;
  border-radius: 24px 13px 27px 14px / 19px 14px 25px 16px;
}

.gummy-button[data-finish="translucent"] .gummy-button__body {
  overflow: hidden;
  padding: 16px 31px 17px 28px;
  border-width: 1.5px;
  border-color: color-mix(in oklch, var(--gummy-rim) 27%, white);
  border-bottom-color: color-mix(in oklch, var(--gummy-rim) 32%, white);
  background:
    radial-gradient(ellipse 46% 32% at 27% 14%, oklch(1 0 0 / 0.62) 0%, transparent 72%),
    radial-gradient(ellipse 60% 76% at 91% 96%, color-mix(in oklch, var(--gummy-core) 28%, transparent), color-mix(in oklch, var(--gummy-depth) 15%, transparent) 46%, transparent 78%),
    linear-gradient(145deg, color-mix(in oklch, var(--gummy-light) 20%, transparent), color-mix(in oklch, var(--gummy-core) 13%, transparent) 50%, color-mix(in oklch, var(--gummy-rim) 28%, transparent));
  backdrop-filter: blur(10px) saturate(1.28);
  box-shadow:
    inset 0 0 0 1.5px oklch(1 0 0 / 0.34),
    inset 2px 3px 5px oklch(1 0 0 / 0.44),
    inset 7px 8px 14px oklch(1 0 0 / 0.1),
    inset -7px -8px 14px color-mix(in oklch, var(--gummy-depth) 9%, transparent),
    0 7px 18px color-mix(in oklch, var(--gummy-shadow) 16%, transparent);
}

.gummy-button[data-finish="translucent"] .gummy-button__body::before {
  z-index: 0;
  inset: 6px 11px 7px 6px;
  padding: 0;
  border: 1px solid oklch(1 0 0 / 0.4);
  border-radius: 16px 8px 18px 9px / 12px 10px 18px 11px;
  background:
    radial-gradient(ellipse 56% 44% at 26% 18%, oklch(1 0 0 / 0.44), transparent 72%),
    linear-gradient(148deg, oklch(0.99 0.012 208 / 0.52), color-mix(in oklch, var(--gummy-light) 30%, transparent) 58%, color-mix(in oklch, var(--gummy-core) 19%, transparent));
  box-shadow:
    inset 2px 2px 4px oklch(1 0 0 / 0.36),
    inset -4px -4px 8px color-mix(in oklch, var(--gummy-core) 13%, transparent);
  mask: none;
  transform-origin: 48% 54%;
  transition: transform 240ms cubic-bezier(0.2, 0.9, 0.25, 1), border-color 180ms ease;
}

.gummy-button[data-finish="translucent"] .gummy-button__body::after {
  z-index: 0;
  top: auto;
  right: -5px;
  bottom: -9px;
  left: auto;
  width: 54px;
  height: 51px;
  border-radius: 48% 52% 68% 32% / 40% 66% 34% 60%;
  border: 0;
  background:
    radial-gradient(ellipse at 28% 22%, oklch(1 0 0 / 0.58), transparent 52%),
    radial-gradient(ellipse at 62% 66%, color-mix(in oklch, var(--gummy-core) 36%, transparent), color-mix(in oklch, var(--gummy-rim) 25%, transparent) 62%, transparent 80%);
  box-shadow:
    inset 2px 2px 4px oklch(1 0 0 / 0.3),
    inset -5px -6px 10px color-mix(in oklch, var(--gummy-depth) 8%, transparent);
  opacity: 0.72;
  transform: rotate(7deg);
  transform-origin: 58% 66%;
  transition: transform 260ms cubic-bezier(0.2, 1.2, 0.28, 1), opacity 180ms ease;
}

:root[data-theme="dark"] .gummy-button[data-finish="translucent"] .gummy-button__body {
  border-color: color-mix(in oklch, var(--gummy-rim) 54%, oklch(1 0 0 / 0.24));
  border-bottom-color: color-mix(in oklch, var(--gummy-depth) 44%, oklch(1 0 0 / 0.2));
  background:
    radial-gradient(ellipse 42% 30% at 27% 14%, oklch(1 0 0 / 0.4) 0%, transparent 72%),
    radial-gradient(ellipse 64% 78% at 91% 96%, color-mix(in oklch, var(--gummy-core) 34%, transparent), color-mix(in oklch, var(--gummy-depth) 22%, transparent) 48%, transparent 79%),
    linear-gradient(145deg, color-mix(in oklch, var(--gummy-light) 14%, transparent), color-mix(in oklch, var(--gummy-core) 19%, transparent) 50%, color-mix(in oklch, var(--gummy-rim) 36%, transparent));
  box-shadow:
    inset 0 0 0 1px oklch(1 0 0 / 0.18),
    inset 2px 3px 5px oklch(1 0 0 / 0.28),
    inset 7px 8px 14px oklch(1 0 0 / 0.07),
    inset -7px -8px 14px color-mix(in oklch, var(--gummy-depth) 16%, transparent),
    0 7px 18px color-mix(in oklch, var(--gummy-shadow) 24%, transparent);
}

:root[data-theme="dark"] .gummy-button[data-finish="translucent"] .gummy-button__body::before {
  border-color: oklch(1 0 0 / 0.26);
  background:
    radial-gradient(ellipse 56% 44% at 26% 18%, oklch(1 0 0 / 0.32), transparent 72%),
    linear-gradient(148deg, oklch(0.94 0.035 208 / 0.46), color-mix(in oklch, var(--gummy-light) 31%, transparent) 58%, color-mix(in oklch, var(--gummy-core) 23%, transparent));
  box-shadow:
    inset 2px 2px 4px oklch(1 0 0 / 0.25),
    inset -4px -4px 8px color-mix(in oklch, var(--gummy-core) 21%, transparent);
}

:root[data-theme="dark"] .gummy-button[data-finish="translucent"] .gummy-button__body::after {
  opacity: 0.8;
}

.gummy-button[data-finish="translucent"] .gummy-button__content {
  z-index: 2;
  transform-origin: center;
  transition: transform 180ms cubic-bezier(0.2, 0.9, 0.25, 1);
}

@media (hover: hover) and (pointer: fine) {
  .gummy-button:not(:disabled):hover .gummy-button__body,
  .gummy-button--preview-hover .gummy-button__body {
    --gummy-shadow-y: 16px;
    filter: saturate(1.06) brightness(1.025);
    transform: translateY(-2px) scaleX(1.012) scaleY(1.012);
  }

  .gummy-button[data-finish="translucent"]:not(:disabled):hover .gummy-button__body::after {
    opacity: 0.8;
    transform: translate(-2px, -1px) rotate(3deg) scale(1.08);
  }
}

.gummy-button:not(:disabled):active .gummy-button__body {
  --gummy-thickness: 1px;
  --gummy-shadow-y: 5px;
  box-shadow:
    inset 0 1px 1px color-mix(in oklch, white 52%, var(--gummy-light)),
    inset 5px 4px 9px oklch(1 0 0 / 0.17),
    inset -4px -3px 10px color-mix(in oklch, var(--gummy-depth) 42%, transparent),
    0 var(--gummy-thickness) 0 var(--gummy-depth),
    0 var(--gummy-shadow-y) 12px var(--gummy-shadow);
  filter: saturate(1.07);
  transform: translateY(5px) scaleX(1.07) scaleY(0.84);
  transition-duration: 70ms;
  transition-timing-function: cubic-bezier(0.2, 0, 0.5, 1);
}

.gummy-button:focus-visible,
.gummy-button--preview-focus {
  outline: 3px solid var(--focus);
  outline-offset: 4px;
}

.gummy-button:focus-visible .gummy-button__body,
.gummy-button--preview-focus .gummy-button__body {
  box-shadow:
    inset 0 1px 1px color-mix(in oklch, white 68%, var(--gummy-light)),
    inset 4px 6px 10px oklch(1 0 0 / 0.22),
    inset -4px -7px 11px color-mix(in oklch, var(--gummy-depth) 34%, transparent),
    0 var(--gummy-thickness) 0 var(--gummy-depth),
    0 var(--gummy-shadow-y) 22px var(--gummy-shadow),
    0 0 0 7px var(--focus-halo);
}

.gummy-button[data-finish="translucent"]:focus-visible {
  outline: none;
}

.gummy-button[data-finish="translucent"]:focus-visible .gummy-button__body {
  border-color: color-mix(in oklch, var(--gummy-rim) 62%, white);
  box-shadow:
    inset 0 0 0 1.5px oklch(1 0 0 / 0.42),
    inset 2px 3px 5px oklch(1 0 0 / 0.58),
    inset 7px 8px 14px oklch(1 0 0 / 0.14),
    inset -7px -8px 14px color-mix(in oklch, var(--gummy-depth) 16%, transparent),
    0 2px 0 color-mix(in oklch, var(--gummy-depth) 22%, transparent),
    0 12px 28px color-mix(in oklch, var(--gummy-shadow) 48%, transparent);
  filter: saturate(1.08) brightness(1.025);
  transform: translateY(-2px) scaleX(1.012) scaleY(1.018);
}

.gummy-button[data-finish="translucent"]:focus-visible .gummy-button__body::after {
  opacity: 0.82;
  transform: translate(-3px, -1px) rotate(2deg) scale(1.1);
}

:root[data-theme="dark"] .gummy-button[data-finish="translucent"]:focus-visible .gummy-button__body {
  border-color: color-mix(in oklch, var(--gummy-rim) 66%, oklch(1 0 0 / 0.28));
  box-shadow:
    inset 0 0 0 1px oklch(1 0 0 / 0.22),
    inset 2px 3px 5px oklch(1 0 0 / 0.34),
    inset 7px 8px 14px oklch(1 0 0 / 0.08),
    inset -7px -8px 14px color-mix(in oklch, var(--gummy-depth) 22%, transparent),
    0 2px 0 color-mix(in oklch, var(--gummy-depth) 22%, transparent),
    0 10px 24px color-mix(in oklch, var(--gummy-shadow) 38%, transparent);
}

.gummy-button[data-finish="translucent"]:not(:disabled):active .gummy-button__body {
  box-shadow:
    inset 0 0 0 1.5px oklch(1 0 0 / 0.34),
    inset 4px 4px 8px oklch(1 0 0 / 0.18),
    inset -5px -4px 10px color-mix(in oklch, var(--gummy-depth) 18%, transparent),
    0 1px 0 color-mix(in oklch, var(--gummy-depth) 20%, transparent),
    0 5px 12px color-mix(in oklch, var(--gummy-shadow) 34%, transparent);
}

.gummy-button[data-finish="translucent"]:not(:disabled):active .gummy-button__body::before {
  transform: translateY(1px) scaleX(1.025) scaleY(0.96);
  transition-duration: 70ms;
}

.gummy-button[data-finish="translucent"]:not(:disabled):active .gummy-button__body::after {
  opacity: 0.88;
  transform: translate(-5px, 4px) rotate(12deg) scaleX(1.18) scaleY(0.78);
  transition-duration: 70ms;
}

.gummy-button[data-finish="translucent"]:not(:disabled):active .gummy-button__content {
  transform: translateY(-1px) scaleX(0.94) scaleY(1.12);
  transition-duration: 70ms;
}

:root[data-theme="dark"] .gummy-button[data-finish="translucent"]:not(:disabled):active .gummy-button__body {
  box-shadow:
    inset 0 0 0 1px oklch(1 0 0 / 0.18),
    inset 4px 4px 8px oklch(1 0 0 / 0.13),
    inset -5px -4px 10px color-mix(in oklch, var(--gummy-depth) 25%, transparent),
    0 1px 0 color-mix(in oklch, var(--gummy-depth) 24%, transparent),
    0 5px 12px color-mix(in oklch, var(--gummy-shadow) 28%, transparent);
}

.gummy-button:disabled:not([data-loading="true"]) {
  cursor: not-allowed;
}

.gummy-button:disabled:not([data-loading="true"]) .gummy-button__body {
  filter: saturate(0.45);
  opacity: 0.54;
  transform: none;
}

.gummy-button[data-loading="true"] {
  cursor: wait;
}

.gummy-button__spinner {
  width: 16px;
  height: 16px;
  border: 2px solid color-mix(in oklch, currentColor 28%, transparent);
  border-top-color: currentColor;
  border-radius: 50%;
  animation: gummy-spin 720ms linear infinite;
}

@keyframes gummy-spin {
  to { transform: rotate(360deg); }
}

@media (prefers-reduced-motion: reduce) {
  .gummy-button:not(:disabled):active .gummy-button__body,
  .gummy-button:not(:disabled):hover .gummy-button__body,
  .gummy-button--preview-hover .gummy-button__body,
  .gummy-button[data-finish="translucent"]:not(:disabled):hover .gummy-button__body::after,
  .gummy-button[data-finish="translucent"]:focus-visible .gummy-button__body::after,
  .gummy-button[data-finish="translucent"]:not(:disabled):active .gummy-button__body::before,
  .gummy-button[data-finish="translucent"]:not(:disabled):active .gummy-button__body::after,
  .gummy-button[data-finish="translucent"]:not(:disabled):active .gummy-button__content {
    transform: none;
  }

  .gummy-button__spinner {
    animation: none;
    border-style: dotted;
  }
}
